// The parts of recording a voice note that are worth being sure about on their
// own: what container to record in, what to call the file, how to say a
// duration, and how loud the microphone currently is.
//
// The recorder itself lives in components/VoiceNotes.tsx, because it is all
// browser objects with a lifetime - a stream, a MediaRecorder, an audio graph -
// and none of that is a function of its arguments.

// The containers a browser might be able to record, best first.
//
// Opus in webm is what chrome and firefox do and what whisper's ffmpeg is
// happiest with; mp4 is safari's answer and is kept last because its recorder
// has historically been the fussiest. Nothing is converted here - the server
// hands whatever this is straight to whisper, which decodes through ffmpeg.
export const RECORD_TYPES = [
    'audio/webm;codecs=opus',
    'audio/webm',
    'audio/ogg;codecs=opus',
    'audio/ogg',
    'audio/mp4',
];

// The first container this browser says it can record. An empty answer is not
// a failure: it means letting MediaRecorder choose, which every browser that
// has one can do.
export function pickMimeType(supported: (t: string) => boolean): string {
    for (const t of RECORD_TYPES) {
        try {
            if (supported(t)) return t;
        } catch {
            // isTypeSupported throws on some older browsers rather than
            // answering false; that is the same answer.
        }
    }
    return '';
}

export function extFor(mime: string): string {
    const m = (mime || '').toLowerCase().split(';')[0].trim();
    if (m.indexOf('webm') >= 0) return 'webm';
    if (m.indexOf('ogg') >= 0) return 'ogg';
    if (m.indexOf('mp4') >= 0 || m.indexOf('m4a') >= 0) return 'm4a';
    if (m.indexOf('mpeg') >= 0 || m.indexOf('mp3') >= 0) return 'mp3';
    if (m.indexOf('wav') >= 0) return 'wav';
    return 'webm';
}

function pad2(n: number): string {
    return String(n).padStart(2, '0');
}

// A length said the way a person reads one: 0:07, 3:42, 1:02:30.
export function formatClock(seconds: number): string {
    if (!isFinite(seconds) || seconds < 0) seconds = 0;
    const t = Math.floor(seconds);
    const h = Math.floor(t / 3600);
    const m = Math.floor(t / 60) % 60;
    const s = t % 60;
    return h > 0 ? `${h}:${pad2(m)}:${pad2(s)}` : `${m}:${pad2(s)}`;
}

export function formatBytes(bytes: number): string {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} kB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function stamp(d: Date): string {
    return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())} ${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
}

// What a note is called before anybody has said otherwise. Dated rather than
// numbered, because a list of voice notes is read by when they were said.
export function defaultHeadline(d: Date): string {
    return `Voice note ${stamp(d)}`;
}

// The name the recording is uploaded under. The server names the file itself -
// this is only what it uses to work out the container.
export function recordingName(mime: string, d: Date): string {
    const t = `${d.getFullYear()}${pad2(d.getMonth() + 1)}${pad2(d.getDate())}-${pad2(d.getHours())}${pad2(d.getMinutes())}${pad2(d.getSeconds())}`;
    return `take-${t}.${extFor(mime)}`;
}

// How loud the microphone is right now, from one frame of the waveform, as 0..1.
//
// Root mean square rather than the peak: a peak meter on speech sits at the top
// of its range and tells you nothing, because a single click is as tall as a
// sentence. The samples are bytes centred on 128, which is why each one is
// taken back to -1..1 first.
export function levelOf(wave: Uint8Array): number {
    if (!wave || wave.length === 0) return 0;
    let sum = 0;
    for (let i = 0; i < wave.length; i++) {
        const v = (wave[i] - 128) / 128;
        sum += v * v;
    }
    const rms = Math.sqrt(sum / wave.length);
    // Speech at a normal distance from a laptop microphone is around 0.05-0.2
    // rms, so the meter is scaled to put that in the middle of its travel
    // rather than in the bottom fifth of it.
    return Math.max(0, Math.min(1, rms * 3.5));
}

// The first words of a transcript, for the line under a take in the list.
export function excerpt(text: string, max: number = 90): string {
    const t = (text || '').replace(/\s+/g, ' ').trim();
    if (t.length <= max) return t;
    return t.substring(0, max - 1).trimEnd() + '…';
}

// A headline suggested by what was actually said: the first sentence, cut to
// something that reads as a title. Punctuation at the end goes, because a
// heading is not a sentence.
export function headlineFromText(text: string, fallback: string): string {
    const t = (text || '').replace(/\s+/g, ' ').trim();
    if (t === '') return fallback;
    let first = t;
    const stop = t.search(/[.!?](\s|$)/);
    if (stop > 0) first = t.substring(0, stop);
    if (first.length > 72) first = first.substring(0, 71).trimEnd() + '…';
    return first.replace(/[,;:\s]+$/, '');
}
