// The hamburger next to the dark mode button: app settings that live in this
// browser. Each group of settings is a submenu that slides open in place rather
// than a second popup, so it stays usable on a phone.

import * as React from 'react';
import Dropdown from '@mui/joy/Dropdown';
import Menu from '@mui/joy/Menu';
import MenuButton from '@mui/joy/MenuButton';
import MenuItem from '@mui/joy/MenuItem';
import IconButton, { IconButtonProps } from '@mui/joy/IconButton';
import ListItemDecorator from '@mui/joy/ListItemDecorator';
import ListItemContent from '@mui/joy/ListItemContent';
import ListSubheader from '@mui/joy/ListSubheader';
import Divider from '@mui/joy/Divider';
import Typography from '@mui/joy/Typography';
import { useColorScheme } from '@mui/joy/styles';

import MenuIcon from '@mui/icons-material/Menu';
import PaletteOutlinedIcon from '@mui/icons-material/PaletteOutlined';
import CheckIcon from '@mui/icons-material/Check';
import ChevronRightRoundedIcon from '@mui/icons-material/ChevronRightRounded';
import ChevronLeftRoundedIcon from '@mui/icons-material/ChevronLeftRounded';

import { ODb } from '../db';
import { useSetting } from '../useSettings';
import { HTML_THEME_AUTO, HTML_THEME_FILE } from '../settings';

// What the theme names read as in the menu. Anything the server reports that is
// not listed here is shown capitalised.
const THEME_LABELS: Record<string, string> = {
    default: 'Default (light)',
    dark: 'Dark',
    docs: 'Docs',
    dnd: 'D&D (parchment)',
};

function themeLabel(name: string): string {
    return THEME_LABELS[name] || (name.charAt(0).toUpperCase() + name.slice(1));
}

type Pane = 'root' | 'htmlTheme';

export default function SettingsMenu(props: IconButtonProps) {
    const { mode } = useColorScheme();
    const [htmlTheme, setHtmlTheme] = useSetting('htmlTheme');
    const [themes, setThemes] = React.useState<string[]>([]);
    const [pane, setPane] = React.useState<Pane>('root');

    // The theme list is whatever stylesheets the server has, asked for once the
    // menu is first opened rather than at startup.
    const loadThemes = React.useCallback(async () => {
        if (themes.length > 0) return;
        const res = await ODb.getHtmlThemes();
        if (res && res.length > 0) setThemes(res);
    }, [themes.length]);

    const choices: { value: string; label: string; hint?: string }[] = [
        { value: HTML_THEME_AUTO, label: 'Match app', hint: mode === 'light' ? 'light' : 'dark' },
        ...themes.map(t => ({ value: t, label: themeLabel(t) })),
        { value: HTML_THEME_FILE, label: 'As written in the file' },
    ];

    return (
        <Dropdown
            onOpenChange={(_, open) => {
                if (open) {
                    loadThemes();
                } else {
                    setPane('root');
                }
            }}
        >
            <MenuButton
                slots={{ root: IconButton }}
                slotProps={{ root: { variant: 'outlined', color: 'neutral', size: 'sm', ...props } }}
                aria-label="Settings"
            >
                <MenuIcon />
            </MenuButton>
            <Menu size="sm" placement="bottom-end" sx={{ minWidth: 230, maxHeight: '70vh', overflow: 'auto' }}>
                {pane === 'root' && [
                    <ListSubheader key="head" sx={{ fontSize: 'xs' }}>Settings</ListSubheader>,
                    <MenuItem
                        key="htmlTheme"
                        // defaultMuiPrevented is the menu's own way of being
                        // told not to close on this click.
                        onClick={(ev) => { (ev as any).defaultMuiPrevented = true; setPane('htmlTheme'); }}
                    >
                        <ListItemDecorator><PaletteOutlinedIcon /></ListItemDecorator>
                        <ListItemContent>
                            Html theme
                            <Typography level="body-xs" sx={{ display: 'block' }}>
                                {(choices.find(c => c.value === htmlTheme) || { label: htmlTheme }).label}
                            </Typography>
                        </ListItemContent>
                        <ChevronRightRoundedIcon />
                    </MenuItem>,
                ]}

                {pane === 'htmlTheme' && [
                    <MenuItem key="back" onClick={(ev) => { (ev as any).defaultMuiPrevented = true; setPane('root'); }}>
                        <ListItemDecorator><ChevronLeftRoundedIcon /></ListItemDecorator>
                        <ListItemContent>Html theme</ListItemContent>
                    </MenuItem>,
                    <Divider key="div" />,
                    ...choices.map(c => (
                        <MenuItem
                            key={c.value}
                            selected={c.value === htmlTheme}
                            onClick={() => setHtmlTheme(c.value)}
                        >
                            <ListItemDecorator>
                                {c.value === htmlTheme ? <CheckIcon /> : null}
                            </ListItemDecorator>
                            <ListItemContent>{c.label}</ListItemContent>
                            {c.hint && <Typography level="body-xs">{c.hint}</Typography>}
                        </MenuItem>
                    )),
                ]}
            </Menu>
        </Dropdown>
    );
}
