const CELL_MIN_WIDTH = 96;

// The three colours the grid uses to say what a cell is to the selection: the
// cell you are on, a cell its formula reads, and a cell its formula also
// writes. They are picked to read the same against a light or a dark surface,
// so they are literal rather than palette tokens.
const ACCENT = {
    active: '#8b5cf6',
    activeSoft: 'rgba(139, 92, 246, 0.16)',
    source: '#22c55e',
    sourceSoft: 'rgba(34, 197, 94, 0.13)',
    peer: '#3b82f6',
    peerSoft: 'rgba(59, 130, 246, 0.13)',
};

// A cell a passed(...) formula writes is reporting a test, so what it says is
// coloured by the verdict rather than left as plain text.
//
// The pass green is a step deeper than the plain palette colour in either
// scheme. The numbered palette steps are the same colour in both, so the two
// are named here and the scheme picks between them - a cell style is a plain
// style object and cannot carry a selector of its own.
const PASSED_CALL = /(^|[^A-Za-z0-9_])passed\s*\(/i;

const verdictVarsSx = {
    '--sheet-passed': 'var(--joy-palette-success-600)',
    '[data-joy-color-scheme="dark"] &': { '--sheet-passed': 'var(--joy-palette-success-400)' },
} as const;

function verdictColor(formula: string | undefined, text: string): string | undefined {
    if (formula === undefined || !PASSED_CALL.test(formula)) return undefined;
    if (/\bfailed\b/i.test(text)) return 'var(--joy-palette-danger-plainColor)';
    if (/\bpassed\b/i.test(text)) return 'var(--sheet-passed)';
    return undefined;
}

// highlight(target, colour, text) says how a cell should look. The server
// evaluates it to the text and drops the colour on the floor, so the colour is
// only ever read back off the formula itself.
//
// The names are the ones the sublime plugin understands, given as tones that
// hold up against a light or a dark surface - literal white and black would
// disappear into one theme or the other.
const HIGHLIGHT_CALL = /(^|[^A-Za-z0-9_])highlight\s*\(/i;

const HIGHLIGHT_COLORS: Record<string, string> = {
    red: '#ef4444',
    green: '#22c55e',
    blue: '#3b82f6',
    purple: '#a855f7',
    violet: '#8b5cf6',
    orange: '#f97316',
    yellow: '#eab308',
    cyan: '#06b6d4',
    pink: '#ec4899',
    magenta: '#d946ef',
    teal: '#14b8a6',
    lime: '#84cc16',
    brown: '#b45309',
    white: '#cbd5e1',
    black: '#64748b',
    gray: '#94a3b8',
    grey: '#94a3b8',
};

// A name we know, or a plain hex. Anything else - a cell reference, an
// expression - is left alone rather than handed to css as a colour.
function namedColor(token: string): string | undefined {
    const t = token.trim().replace(/^["']|["']$/g, '').toLowerCase();
    if (HIGHLIGHT_COLORS[t] !== undefined) return HIGHLIGHT_COLORS[t];
    if (/^#([0-9a-f]{3}|[0-9a-f]{6})$/.test(t)) return t;
    return undefined;
}

// The second argument of the highlight(...) call in a formula. Arguments are
// walked rather than split on commas, so a comma inside a nested call or a
// quoted string does not read as the end of one.
function highlightColor(formula: string | undefined): string | undefined {
    if (formula === undefined) return undefined;
    const m = HIGHLIGHT_CALL.exec(formula);
    if (!m) return undefined;
    const args: string[] = [];
    let start = m.index + m[0].length;
    let depth = 0;
    let quote = '';
    for (let i = start; i < formula.length; i++) {
        const ch = formula[i];
        if (quote !== '') {
            if (ch === quote) quote = '';
            continue;
        }
        if (ch === '"' || ch === "'") quote = ch;
        else if (ch === '(') depth += 1;
        else if (ch === ')') {
            if (depth === 0) {
                args.push(formula.slice(start, i));
                break;
            }
            depth -= 1;
        } else if (ch === ',' && depth === 0) {
            args.push(formula.slice(start, i));
            start = i + 1;
            if (args.length > 1) break;
        }
    }
    return args.length > 1 ? namedColor(args[1]) : undefined;
}

// The warm tint under a cell some formula writes, and how far the corner mark
// on it fades back. Both are held barely off the surface: they are there to be
// noticed when looked for, not to colour a table of computed columns.
const COMPUTED_WASH = 'color-mix(in srgb, var(--joy-palette-warning-400) 5%, var(--joy-palette-background-surface))';
const COMPUTED_MARK_OPACITY = 0.45;

// A sheen thin enough to be felt rather than seen, and neutral enough to sit
// on either theme: a highlight along the top, a shadow along the bottom.
const GLOSS = 'linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0) 52%, rgba(0,0,0,0.035))';

const panelSx = {
    borderRadius: 'md',
    backgroundImage: `${GLOSS}, linear-gradient(180deg, var(--joy-palette-background-surface), var(--joy-palette-background-level1))`,
} as const;

// A rule that fades out at both ends, so grouping the tools costs no hard edges.
const toolSepSx = {
    width: '1px',
    alignSelf: 'stretch',
    mx: 0.5,
    my: 0.25,
    flex: 'none',
    background: 'linear-gradient(180deg, transparent, var(--joy-palette-divider), transparent)',
} as const;

const toolButtonSx = {
    borderRadius: '7px',
    '--IconButton-size': '30px',
    color: 'text.secondary',
    transition: 'background-color 120ms, color 120ms',
    '&:hover': { color: 'text.primary' },
} as const;

function clamp(v: number, lo: number, hi: number): number {
    return Math.min(Math.max(v, lo), hi);
}

// The selected block, read as chartable series both ways round. Whichever way
// it is read, the labels come from the header line and the leading label column
// when the selection leaves those outside itself, and from the org address of
// the row or column when it does not.
function chartInput(rows: TableRowData[], rect: { r0: number; r1: number; c0: number; c1: number }, headerRow: number): ChartInput {
    const nums = OT.orgRowNumbers(rows);
    // A header line inside a taller selection is a label, not a reading.
    const skipHeader = headerRow >= 0 && rect.r1 > rect.r0;

    const dataRows: number[] = [];
    for (let r = rect.r0; r <= rect.r1; r++) {
        if (r >= rows.length || OT.isSep(rows[r]) || OT.isAdvanced(rows[r])) continue;
        if (skipHeader && r === headerRow) continue;
        dataRows.push(r);
    }
    const cols: number[] = [];
    for (let c = rect.c0; c <= rect.c1; c++) cols.push(c);

    const headerOutside = headerRow >= 0 && (skipHeader || headerRow < rect.r0 || headerRow > rect.r1);
    const colLabel = (c: number) => (headerOutside ? OT.cellAt(rows, headerRow, c).trim() : '') || `$${c + 1}`;
    const rowLabel = (r: number) => (rect.c0 > 0 ? OT.cellAt(rows, r, 0).trim() : '') || `@${nums[r]}`;

    return {
        byRow: {
            labels: cols.map(colLabel),
            series: dataRows.map(r => ({ name: rowLabel(r), points: cols.map(c => OT.toNumber(OT.cellAt(rows, r, c))) })),
        },
        byCol: {
            labels: dataRows.map(rowLabel),
            series: cols.map(c => ({ name: colLabel(c), points: dataRows.map(r => OT.toNumber(OT.cellAt(rows, r, c))) })),
        },
        // A wide, short selection reads as a line per row; anything else reads
        // as a line per column, which is how a table of readings is usually laid out.
        prefer: cols.length > dataRows.length ? 'byRow' : 'byCol',
    };
}

// The cell the keyboard lands on when moving over a rule, rules hold no value.
function skipSeparators(rows: TableRowData[], r: number, dir: number): number {
    let i = r;
    while (i >= 0 && i < rows.length && OT.isSep(rows[i])) {
        i += dir === 0 ? 1 : dir;
    }
    if (i < 0 || i >= rows.length) {
        // Nothing that way, walk back to the nearest row that holds cells.
        i = r;
        while (i >= 0 && i < rows.length && OT.isSep(rows[i])) i -= dir === 0 ? 1 : dir;
    }
    return clamp(i, 0, Math.max(0, rows.length - 1));
}

export default function Spreadsheet(props: SpreadsheetProps) {
    const { table } = props;

    const [rows, setRows] = React.useState<TableRowData[]>(() => OT.normalize(table.Data || []));
    const [formulas, setFormulas] = React.useState<string[]>(table.FormulaList || []);
    const [name, setName] = React.useState<string>(table.Name || '');
    const [dirty, setDirty] = React.useState(false);
    const [undo, setUndo] = React.useState<Snapshot[]>([]);
    const [redo, setRedo] = React.useState<Snapshot[]>([]);

    const [anchor, setAnchor] = React.useState<Cursor>({ r: 0, c: 0 });
    const [focus, setFocus] = React.useState<Cursor>({ r: 0, c: 0 });
    const [edit, setEdit] = React.useState<{ r: number; c: number; value: string } | null>(null);
    const [bar, setBar] = React.useState<string | null>(null);
    const [showFormulas, setShowFormulas] = React.useState(false);
    const [dragging, setDragging] = React.useState(false);
    const [chartOpen, setChartOpen] = React.useState(false);

    const gridRef = React.useRef<HTMLDivElement>(null);
    const editRef = React.useRef<HTMLInputElement>(null);

    // A freshly loaded (or freshly saved) table replaces whatever is on screen.
    React.useEffect(() => {
        setRows(OT.normalize(table.Data || []));
        setFormulas(table.FormulaList || []);
        setName(table.Name || '');
        setDirty(false);
        setUndo([]);
        setRedo([]);
        setEdit(null);
        setBar(null);
    }, [table]);

    React.useEffect(() => {
        if (props.onDirtyChange) props.onDirtyChange(dirty);
    }, [dirty, props]);

    // Focus the editor when an edit starts, and only then. Re-running this on
    // every keystroke would put the caret back to the start of the cell.
    const editKey = edit === null ? '' : `${edit.r},${edit.c}`;
    React.useEffect(() => {
        if (editKey !== '' && editRef.current) {
            const input = editRef.current;
            input.focus();
            const end = input.value.length;
            input.setSelectionRange(end, end);
        }
    }, [editKey]);

    const colCount = OT.columnCount(rows);
    const colNames = React.useMemo(() => OT.columnNames(rows), [rows]);
    const targets = React.useMemo(() => OT.formulaTargets(formulas, rows, colNames), [formulas, rows, colNames]);

    const rect = {
        r0: Math.min(anchor.r, focus.r),
        r1: Math.max(anchor.r, focus.r),
        c0: Math.min(anchor.c, focus.c),
        c1: Math.max(anchor.c, focus.c),
    };

    function apply(next: Partial<Snapshot>) {
        setUndo(u => [...u.slice(-199), { rows, formulas, name }]);
        setRedo([]);
        if (next.rows !== undefined) setRows(OT.normalize(next.rows));
        if (next.formulas !== undefined) setFormulas(next.formulas);
        if (next.name !== undefined) setName(next.name);
        setDirty(true);
    }

    function doUndo() {
        if (undo.length === 0) return;
        const prev = undo[undo.length - 1];
        setUndo(u => u.slice(0, -1));
        setRedo(r => [...r, { rows, formulas, name }]);
        setRows(prev.rows);
        setFormulas(prev.formulas);
        setName(prev.name);
        setDirty(true);
    }

    function doRedo() {
        if (redo.length === 0) return;
        const next = redo[redo.length - 1];
        setRedo(r => r.slice(0, -1));
        setUndo(u => [...u, { rows, formulas, name }]);
        setRows(next.rows);
        setFormulas(next.formulas);
        setName(next.name);
        setDirty(true);
    }

    function setCells(changes: { r: number; c: number; value: string }[]) {
        const next = rows.map(r => ({ ...r, Cells: r.Cells.slice() }));
        let width = colCount;
        for (const ch of changes) {
            if (ch.c + 1 > width) width = ch.c + 1;
        }
        while (next.length === 0) next.push(OT.emptyRow(width));
        for (const ch of changes) {
            while (next.length <= ch.r) next.push(OT.emptyRow(width));
            const cells = next[ch.r].Cells;
            while (cells.length <= ch.c) cells.push('');
            if (next[ch.r].Kind === 'sep') continue;
            cells[ch.c] = ch.value;
        }
        apply({ rows: next });
    }

    function moveTo(r: number, c: number, extend: boolean) {
        const nr = clamp(r, 0, Math.max(0, rows.length - 1));
        const nc = clamp(c, 0, Math.max(0, colCount - 1));
        if (extend) {
            setFocus({ r: nr, c: nc });
        } else {
            setAnchor({ r: nr, c: nc });
            setFocus({ r: nr, c: nc });
        }
        setBar(null);
    }

    function startEdit(r: number, c: number, initial?: string) {
        if (OT.isSep(rows[r])) return;
        setEdit({ r, c, value: initial !== undefined ? initial : OT.cellAt(rows, r, c) });
    }

    function commitEdit(move: { dr: number; dc: number } | null) {
        if (!edit) return;
        const { r, c, value } = edit;
        setEdit(null);
        if (value.startsWith('=')) {
            apply({ formulas: OT.setCellFormula(formulas, rows, r, c, value.slice(1)) });
        } else if (value !== OT.cellAt(rows, r, c)) {
            setCells([{ r, c, value }]);
        }
        if (move) {
            let nr = clamp(r + move.dr, 0, rows.length - 1);
            if (move.dr !== 0) nr = skipSeparators(rows, nr, move.dr);
            moveTo(nr, c + move.dc, false);
        }
        focusGrid();
    }

    function focusGrid() {
        window.setTimeout(() => {
            if (gridRef.current) gridRef.current.focus();
        }, 0);
    }

    function clearSelection() {
        const changes: { r: number; c: number; value: string }[] = [];
        for (let r = rect.r0; r <= rect.r1; r++) {
            if (OT.isSep(rows[r])) continue;
            for (let c = rect.c0; c <= rect.c1; c++) changes.push({ r, c, value: '' });
        }
        if (changes.length > 0) setCells(changes);
    }

    function fillDown() {
        if (rect.r1 <= rect.r0) return;
        const changes: { r: number; c: number; value: string }[] = [];
        for (let c = rect.c0; c <= rect.c1; c++) {
            const src = OT.cellAt(rows, rect.r0, c);
            for (let r = rect.r0 + 1; r <= rect.r1; r++) {
                if (OT.isSep(rows[r])) continue;
                changes.push({ r, c, value: src });
            }
        }
        if (changes.length > 0) setCells(changes);
    }

    function insertRow(at: number, kind: 'data' | 'sep') {
        const next = rows.slice();
        next.splice(at, 0, kind === 'sep' ? OT.sepRow(colCount) : OT.emptyRow(colCount));
        apply({ rows: next });
        moveTo(at, anchor.c, false);
    }

    function deleteRows() {
        if (rows.length - (rect.r1 - rect.r0 + 1) < 1) return;
        const next = rows.filter((_, i) => i < rect.r0 || i > rect.r1);
        apply({ rows: next });
        moveTo(Math.min(rect.r0, next.length - 1), anchor.c, false);
    }

    function insertCol(at: number) {
        const next = rows.map(r => {
            const cells = r.Cells.slice();
            cells.splice(at, 0, '');
            return { ...r, Cells: cells };
        });
        apply({ rows: next });
        moveTo(anchor.r, at, false);
    }

    function deleteCols() {
        if (colCount - (rect.c1 - rect.c0 + 1) < 1) return;
        const next = rows.map(r => ({ ...r, Cells: r.Cells.filter((_, i) => i < rect.c0 || i > rect.c1) }));
        apply({ rows: next });
        moveTo(anchor.r, Math.max(0, rect.c0 - 1), false);
    }

    function selectionCells(): string[][] {
        const out: string[][] = [];
        for (let r = rect.r0; r <= rect.r1; r++) {
            const line: string[] = [];
            for (let c = rect.c0; c <= rect.c1; c++) line.push(OT.cellAt(rows, r, c));
            out.push(line);
        }
        return out;
    }

    function onCopy(e: React.ClipboardEvent) {
        if (edit) return;
        e.clipboardData.setData('text/plain', OT.tsvFromCells(selectionCells()));
        e.preventDefault();
    }

    function onCut(e: React.ClipboardEvent) {
        if (edit) return;
        onCopy(e);
        clearSelection();
    }

    function onPaste(e: React.ClipboardEvent) {
        if (edit) return;
        const text = e.clipboardData.getData('text/plain');
        if (!text) return;
        e.preventDefault();
        const block = OT.cellsFromTsv(text);
        const next = rows.map(r => ({ ...r, Cells: r.Cells.slice() }));
        const width = Math.max(colCount, anchor.c + Math.max(...block.map(b => b.length)));
        for (let i = 0; i < block.length; i++) {
            const r = anchor.r + i;
            while (next.length <= r) next.push(OT.emptyRow(width));
            if (next[r].Kind === 'sep') continue;
            for (let j = 0; j < block[i].length; j++) {
                const c = anchor.c + j;
                while (next[r].Cells.length <= c) next[r].Cells.push('');
                next[r].Cells[c] = block[i][j];
            }
        }
        apply({ rows: next });
        setFocus({ r: clamp(anchor.r + block.length - 1, 0, next.length - 1), c: clamp(anchor.c + Math.max(...block.map(b => b.length)) - 1, 0, width - 1) });
    }

    function onKeyDown(e: React.KeyboardEvent) {
        if (edit) return;
        const meta = e.ctrlKey || e.metaKey;
        if (meta && e.key.toLowerCase() === 's') {
            e.preventDefault();
            props.onSave(rows, formulas, name, false);
            return;
        }
        if (meta && e.key.toLowerCase() === 'z') {
            e.preventDefault();
            if (e.shiftKey) doRedo(); else doUndo();
            return;
        }
        if (meta && e.key.toLowerCase() === 'y') {
            e.preventDefault();
            doRedo();
            return;
        }
        if (meta && e.key.toLowerCase() === 'd') {
            e.preventDefault();
            fillDown();
            return;
        }
        if (meta && e.key.toLowerCase() === 'g') {
            e.preventDefault();
            if (chartable) setChartOpen(true);
            return;
        }
        switch (e.key) {
            case 'ArrowUp':
                e.preventDefault();
                moveTo(meta ? 0 : skipSeparators(rows, focus.r - 1, -1), focus.c, e.shiftKey);
                return;
            case 'ArrowDown':
                e.preventDefault();
                moveTo(meta ? rows.length - 1 : skipSeparators(rows, focus.r + 1, 1), focus.c, e.shiftKey);
                return;
            case 'ArrowLeft':
                e.preventDefault();
                moveTo(focus.r, meta ? 0 : focus.c - 1, e.shiftKey);
                return;
            case 'ArrowRight':
                e.preventDefault();
                moveTo(focus.r, meta ? colCount - 1 : focus.c + 1, e.shiftKey);
                return;
            case 'Home':
                e.preventDefault();
                moveTo(meta ? 0 : focus.r, 0, e.shiftKey);
                return;
            case 'End':
                e.preventDefault();
                moveTo(meta ? rows.length - 1 : focus.r, colCount - 1, e.shiftKey);
                return;
            case 'Tab':
                e.preventDefault();
                moveTo(anchor.r, anchor.c + (e.shiftKey ? -1 : 1), false);
                return;
            case 'Enter':
                e.preventDefault();
                if (OT.isSep(rows[anchor.r])) {
                    moveTo(skipSeparators(rows, anchor.r + 1, 1), anchor.c, false);
                } else {
                    startEdit(anchor.r, anchor.c);
                }
                return;
            case 'F2':
                e.preventDefault();
                startEdit(anchor.r, anchor.c);
                return;
            case 'Delete':
            case 'Backspace':
                e.preventDefault();
                clearSelection();
                return;
            case 'Escape':
                e.preventDefault();
                moveTo(anchor.r, anchor.c, false);
                return;
            default:
                break;
        }
        if (!meta && !e.altKey && e.key.length === 1) {
            e.preventDefault();
            startEdit(anchor.r, anchor.c, e.key);
        }
    }

    // The formula bar shows the formula that writes the cell when there is one,
    // and the text the cell holds when there is not.
    const cellFormula = targets[`${anchor.r},${anchor.c}`];
    const parsedCellFormula = cellFormula ? OT.parseFormula(cellFormula) : null;
    const ownFormula = parsedCellFormula !== null && parsedCellFormula.target === OT.cellRef(rows, anchor.r, anchor.c);
    const barText = bar !== null
        ? bar
        : parsedCellFormula
            ? '=' + parsedCellFormula.body
            : OT.cellAt(rows, anchor.r, anchor.c);

    // What the formula behind the selected cell touches: the cells it reads and
    // the other cells it writes.
    const trace = React.useMemo(() => {
        const sources: Record<string, boolean> = {};
        const peers: Record<string, boolean> = {};
        if (cellFormula) {
            for (const s of OT.formulaSources(cellFormula, rows, colNames, anchor.r, anchor.c)) {
                sources[`${s.r},${s.c}`] = true;
            }
            for (const t of OT.formulaPeers(cellFormula, rows, colNames, anchor.r, anchor.c)) {
                peers[`${t.r},${t.c}`] = true;
            }
        }
        delete sources[`${anchor.r},${anchor.c}`];
        return { sources, peers, sourceCount: Object.keys(sources).length, peerCount: Object.keys(peers).length };
    }, [cellFormula, rows, colNames, anchor.r, anchor.c]);

    function commitBar(value: string) {
        setBar(null);
        if (OT.isSep(rows[anchor.r])) return;
        if (value.startsWith('=')) {
            apply({ formulas: OT.setCellFormula(formulas, rows, anchor.r, anchor.c, value.slice(1)) });
        } else {
            let nextFormulas = formulas;
            if (ownFormula) {
                nextFormulas = OT.setCellFormula(formulas, rows, anchor.r, anchor.c, '');
            }
            const next = rows.map(r => ({ ...r, Cells: r.Cells.slice() }));
            while (next[anchor.r].Cells.length <= anchor.c) next[anchor.r].Cells.push('');
            next[anchor.r].Cells[anchor.c] = value;
            apply({ rows: next, formulas: nextFormulas });
        }
        focusGrid();
    }

    // Selection summary, the way a spreadsheet shows one along the bottom.
    const stats = React.useMemo(() => {
        let count = 0;
        let numeric = 0;
        let sum = 0;
        let min = Number.POSITIVE_INFINITY;
        let max = Number.NEGATIVE_INFINITY;
        for (let r = rect.r0; r <= rect.r1; r++) {
            if (r >= rows.length || OT.isSep(rows[r])) continue;
            for (let c = rect.c0; c <= rect.c1; c++) {
                const v = OT.cellAt(rows, r, c);
                if (v.trim() !== '') count += 1;
                const n = OT.toNumber(v);
                if (n !== null) {
                    numeric += 1;
                    sum += n;
                    min = Math.min(min, n);
                    max = Math.max(max, n);
                }
            }
        }
        return { count, numeric, sum, min, max };
    }, [rows, rect.r0, rect.r1, rect.c0, rect.c1]);

    const orgRows = React.useMemo(() => OT.orgRowNumbers(rows), [rows]);
    const headerRow = OT.hasHeader(rows) ? 0 : -1;

    // Keyed on the edges of the selection rather than on the rect itself, which
    // is a fresh object every render.
    const chartSeries = React.useMemo(
        () => chartInput(rows, { r0: rect.r0, r1: rect.r1, c0: rect.c0, c1: rect.c1 }, headerRow),
        [rows, rect.r0, rect.r1, rect.c0, rect.c1, headerRow],
    );
    const chartable = chartSeries.byRow.series.some(s => s.points.some(p => p !== null));

    function cellStyle(r: number, c: number) {
        const key = `${r},${c}`;
        const selected = r >= rect.r0 && r <= rect.r1 && c >= rect.c0 && c <= rect.c1;
        const isAnchor = r === anchor.r && c === anchor.c;
        const isSource = trace.sources[key] === true;
        const isPeer = !isAnchor && trace.peers[key] === true;
        const computed = targets[key] !== undefined;
        const verdict = verdictColor(targets[key], OT.cellAt(rows, r, c));
        const painted = highlightColor(targets[key]);

        // Inner ring for the cell you are on, an outer one for the cells the
        // same formula also writes, so the two never sit on top of each other.
        // The colour a highlight(...) asks for goes on last, under all of them,
        // since those three say what is happening right now.
        const rings: string[] = [];
        if (isAnchor) rings.push(`inset 0 0 0 2px ${ACCENT.active}`);
        if (isSource) rings.push(`inset 0 0 0 1px ${ACCENT.source}`);
        if (isPeer) rings.push(`0 0 0 2px ${ACCENT.peer}`);
        if (painted) rings.push(`inset 0 0 0 1px ${painted}`);

        // A highlighted cell keeps its colour under the plain warning wash a
        // computed cell gets, but gives way to the selection, which has to stay
        // readable across a block of them.
        const background = isAnchor
            ? ACCENT.activeSoft
            : isSource
                ? ACCENT.sourceSoft
                : isPeer
                    ? ACCENT.peerSoft
                    : selected
                        ? 'var(--joy-palette-primary-softBg)'
                        : painted
                            ? `color-mix(in srgb, ${painted} 16%, transparent)`
                            : computed
                                ? COMPUTED_WASH
                                : r === headerRow
                                    ? 'var(--joy-palette-background-level1)'
                                    : 'var(--joy-palette-background-surface)';

        return {
            position: 'relative' as const,
            // Dotted inside, so the grid reads as guides rather than as a cage.
            // A traced or a painted cell takes a solid edge in its own colour.
            // A painted cell keeps its own edge even while it is being traced,
            // the trace still shows as the ring just inside it.
            border: painted
                ? `1px solid ${painted}`
                : isSource
                    ? `1px solid ${ACCENT.source}`
                    : '1px dotted var(--joy-palette-neutral-outlinedBorder)',
            boxShadow: rings.length > 0 ? rings.join(', ') : 'none',
            // Under the sticky headings (4 and up), over the plain cells.
            zIndex: isAnchor ? 3 : isSource || isPeer ? 2 : undefined,
            backgroundColor: background,
            color: verdict !== undefined ? verdict : undefined,
            fontWeight: r === headerRow ? 600 : 400,
            fontFamily: 'var(--joy-fontFamily-code, monospace)',
            fontSize: '13px',
            padding: '3px 7px',
            minWidth: CELL_MIN_WIDTH,
            maxWidth: 360,
            height: 28,
            whiteSpace: 'pre' as const,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            cursor: 'cell',
            userSelect: 'none' as const,
        };
    }

    // The row and column headings, tinted while their line holds the cursor.
    function headerCellStyle(active: boolean) {
        return {
            borderRight: '1px solid var(--joy-palette-divider)',
            borderBottom: '1px solid var(--joy-palette-divider)',
            backgroundColor: active ? ACCENT.activeSoft : 'var(--joy-palette-background-level1)',
            backgroundImage: active ? 'none' : GLOSS,
            color: active ? ACCENT.active : 'var(--joy-palette-text-tertiary)',
            fontFamily: 'var(--joy-fontFamily-code, monospace)',
            fontSize: '11px',
            fontWeight: 600,
            letterSpacing: '0.03em',
            textAlign: 'center' as const,
            padding: '3px 4px',
            position: 'sticky' as const,
            cursor: 'pointer',
            userSelect: 'none' as const,
        };
    }

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, minHeight: 0, flex: 1, ...verdictVarsSx }}>
            {/* Toolbar and formula bar, one raised panel */}
            <Sheet variant="outlined" sx={{ ...panelSx, p: 0.75, display: 'flex', flexDirection: 'column', gap: 0.75, boxShadow: 'xs' }}>
                <Box sx={{ display: 'flex', gap: 0.25, alignItems: 'center', flexWrap: 'wrap' }}>
                    <Button
                        size="sm"
                        color={dirty ? 'primary' : 'neutral'}
                        variant={dirty ? 'solid' : 'outlined'}
                        startDecorator={props.saving ? <CircularProgress size="sm" /> : <SaveIcon />}
                        disabled={props.saving}
                        onClick={() => props.onSave(rows, formulas, name, false)}
                        sx={{
                            borderRadius: '7px',
                            backgroundImage: dirty ? GLOSS : undefined,
                            boxShadow: dirty ? 'sm' : 'none',
                        }}
                    >
                        Save
                    </Button>
                    <Button
                        size="sm"
                        variant="outlined"
                        color="neutral"
                        startDecorator={<CalculateIcon />}
                        disabled={props.saving}
                        onClick={() => props.onSave(rows, formulas, name, true)}
                        sx={{ ml: 0.5, borderRadius: '7px', backgroundImage: GLOSS }}
                    >
                        Recalculate
                    </Button>
                    <Box sx={toolSepSx} />
                    <Tooltip title="Undo (Ctrl+Z)" size="sm">
                        <span><IconButton size="sm" variant="plain" sx={toolButtonSx} disabled={undo.length === 0} onClick={doUndo}><UndoIcon /></IconButton></span>
                    </Tooltip>
                    <Tooltip title="Redo (Ctrl+Shift+Z)" size="sm">
                        <span><IconButton size="sm" variant="plain" sx={toolButtonSx} disabled={redo.length === 0} onClick={doRedo}><RedoIcon /></IconButton></span>
                    </Tooltip>
                    <Box sx={toolSepSx} />
                    <Tooltip title="Insert row above" size="sm">
                        <IconButton size="sm" variant="plain" sx={toolButtonSx} onClick={() => insertRow(rect.r0, 'data')}>
                            <TableRowsIcon sx={{ transform: 'scaleY(-1)' }} />
                        </IconButton>
                    </Tooltip>
                    <Tooltip title="Insert row below" size="sm">
                        <IconButton size="sm" variant="plain" sx={toolButtonSx} onClick={() => insertRow(rect.r1 + 1, 'data')}><TableRowsIcon /></IconButton>
                    </Tooltip>
                    <Tooltip title="Insert horizontal rule below" size="sm">
                        <IconButton size="sm" variant="plain" sx={toolButtonSx} onClick={() => insertRow(rect.r1 + 1, 'sep')}><HorizontalRuleIcon /></IconButton>
                    </Tooltip>
                    <Tooltip title="Delete selected rows" size="sm">
                        <IconButton size="sm" variant="plain" color="danger" sx={toolButtonSx} onClick={deleteRows}><DeleteIcon /></IconButton>
                    </Tooltip>
                    <Box sx={toolSepSx} />
                    <Tooltip title="Insert column left" size="sm">
                        <IconButton size="sm" variant="plain" sx={toolButtonSx} onClick={() => insertCol(rect.c0)}><ViewColumnIcon sx={{ transform: 'scaleX(-1)' }} /></IconButton>
                    </Tooltip>
                    <Tooltip title="Insert column right" size="sm">
                        <IconButton size="sm" variant="plain" sx={toolButtonSx} onClick={() => insertCol(rect.c1 + 1)}><ViewColumnIcon /></IconButton>
                    </Tooltip>
                    <Tooltip title="Delete selected columns" size="sm">
                        <IconButton size="sm" variant="plain" color="danger" sx={toolButtonSx} onClick={deleteCols}><ViewColumnIcon color="error" /></IconButton>
                    </Tooltip>
                    <Box sx={toolSepSx} />
                    <Tooltip title="Fill down (Ctrl+D)" size="sm">
                        <IconButton size="sm" variant="plain" sx={toolButtonSx} onClick={fillDown}><VerticalAlignBottomIcon /></IconButton>
                    </Tooltip>
                    <Tooltip title="Chart the selected rows or columns (Ctrl+G)" size="sm">
                        <span>
                            <IconButton size="sm" variant="plain" sx={toolButtonSx} disabled={!chartable} onClick={() => setChartOpen(true)}>
                                <ShowChartIcon />
                            </IconButton>
                        </span>
                    </Tooltip>
                    <Box sx={{ flex: 1, minWidth: 8 }} />
                    <Input
                        size="sm"
                        placeholder="#+NAME:"
                        value={name}
                        startDecorator={<Typography level="body-xs" sx={{ color: 'text.tertiary' }}>name</Typography>}
                        onChange={e => apply({ name: e.target.value })}
                        sx={{ width: 220, borderRadius: '7px', backgroundImage: GLOSS }}
                    />
                </Box>

                <Divider sx={{ '--Divider-lineColor': 'var(--joy-palette-divider)' }} />

                {/* Formula bar */}
                <Box sx={{ display: 'flex', gap: 0.75, alignItems: 'center' }}>
                    <Chip
                        size="sm"
                        variant="soft"
                        color="neutral"
                        sx={{
                            fontFamily: 'monospace',
                            minWidth: 76,
                            justifyContent: 'center',
                            borderRadius: '7px',
                            color: ACCENT.active,
                            backgroundColor: ACCENT.activeSoft,
                            boxShadow: `inset 0 0 0 1px ${ACCENT.activeSoft}`,
                        }}
                    >
                        {OT.cellRef(rows, anchor.r, anchor.c) || '—'}
                    </Chip>
                    <FunctionsIcon fontSize="small" sx={{ color: 'text.tertiary' }} />
                    <Input
                        size="sm"
                        value={barText}
                        placeholder="Value, or =formula to compute this cell"
                        onChange={e => setBar(e.target.value)}
                        onKeyDown={e => {
                            if (e.key === 'Enter') {
                                e.preventDefault();
                                commitBar(bar !== null ? bar : barText);
                            } else if (e.key === 'Escape') {
                                e.preventDefault();
                                setBar(null);
                                focusGrid();
                            }
                            e.stopPropagation();
                        }}
                        sx={{ flex: 1, fontFamily: 'monospace', borderRadius: '7px', backgroundImage: GLOSS }}
                    />
                    <Tooltip title="Show the #+TBLFM: formulas of this table" size="sm">
                        <IconButton
                            size="sm"
                            variant={showFormulas ? 'solid' : 'outlined'}
                            color="neutral"
                            sx={{ borderRadius: '7px', backgroundImage: GLOSS }}
                            onClick={() => setShowFormulas(!showFormulas)}
                        >
                            {showFormulas ? <ExpandLessIcon /> : <ExpandMoreIcon />}
                        </IconButton>
                    </Tooltip>
                </Box>
            </Sheet>

            {/* Kept in the layout whether it says anything or not, so selecting a
                computed cell does not shove the grid down a line. */}
            <Box sx={{ display: 'flex', gap: 1.5, alignItems: 'center', minHeight: '1.25rem', overflow: 'hidden' }}>
                <Typography level="body-xs" sx={{ color: 'text.tertiary', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {cellFormula && !ownFormula
                        ? <>This cell is written by the range formula <code>{cellFormula}</code>. Typing a value here holds until the next recalculation.</>
                        : ''}
                </Typography>
                {cellFormula && trace.sourceCount > 0 && <Legend color={ACCENT.source} label={`${trace.sourceCount} read`} />}
                {cellFormula && trace.peerCount > 0 && <Legend color={ACCENT.peer} label={`${trace.peerCount} also written`} />}
            </Box>

            {showFormulas && (
                <Sheet variant="outlined" sx={{ p: 1, borderRadius: 'sm', display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                    {formulas.length === 0 && (
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            No formulas. Add one like <code>$4=$2*$3</code> or <code>@5$4=vsum(@2$4..@4$4)</code>.
                        </Typography>
                    )}
                    {formulas.map((f, i) => (
                        <Box key={i} sx={{ display: 'flex', gap: 0.5, alignItems: 'center' }}>
                            <Input
                                size="sm"
                                value={f}
                                sx={{ flex: 1, fontFamily: 'monospace' }}
                                onChange={e => {
                                    const next = formulas.slice();
                                    next[i] = e.target.value;
                                    apply({ formulas: next });
                                }}
                            />
                            <IconButton size="sm" variant="plain" color="danger" onClick={() => apply({ formulas: formulas.filter((_, j) => j !== i) })}>
                                <DeleteIcon />
                            </IconButton>
                        </Box>
                    ))}
                    <Button
                        size="sm"
                        variant="plain"
                        startDecorator={<AddIcon />}
                        sx={{ alignSelf: 'flex-start' }}
                        onClick={() => apply({ formulas: [...formulas, ''] })}
                    >
                        Add formula
                    </Button>
                </Sheet>
            )}

            {/* Grid */}
            <Sheet
                variant="outlined"
                sx={{ flex: 1, minHeight: 240, overflow: 'auto', borderRadius: 'md', boxShadow: 'xs' }}
            >
                <Box
                    ref={gridRef}
                    tabIndex={0}
                    onKeyDown={onKeyDown}
                    onCopy={onCopy}
                    onCut={onCut}
                    onPaste={onPaste}
                    onMouseUp={() => setDragging(false)}
                    sx={{ outline: 'none', display: 'inline-block', minWidth: '100%' }}
                >
                    <table style={{ borderCollapse: 'collapse' }}>
                        <thead>
                            <tr>
                                <th style={{ ...headerCellStyle(false), left: 0, zIndex: 6, top: 0, minWidth: 46 }} />
                                {Array.from({ length: colCount }, (_, c) => (
                                    <th
                                        key={c}
                                        style={{ ...headerCellStyle(c >= rect.c0 && c <= rect.c1), top: 0, zIndex: 5, minWidth: CELL_MIN_WIDTH }}
                                        onClick={() => {
                                            setAnchor({ r: 0, c });
                                            setFocus({ r: Math.max(0, rows.length - 1), c });
                                            focusGrid();
                                        }}
                                    >
                                        ${c + 1}
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {rows.map((row, r) => (
                                <tr key={r}>
                                    <td
                                        style={{ ...headerCellStyle(r >= rect.r0 && r <= rect.r1), left: 0, zIndex: 4, minWidth: 46 }}
                                        onClick={() => {
                                            setAnchor({ r, c: 0 });
                                            setFocus({ r, c: Math.max(0, colCount - 1) });
                                            focusGrid();
                                        }}
                                    >
                                        {orgRows[r] > 0 ? `@${orgRows[r]}` : '—'}
                                    </td>
                                    {OT.isSep(row) ? (
                                        <td colSpan={colCount} style={{ padding: 0, height: 9, backgroundColor: 'var(--joy-palette-background-level1)', backgroundImage: GLOSS }}>
                                            <Box sx={{ height: '1px', mx: 0.75, background: 'linear-gradient(90deg, transparent, var(--joy-palette-neutral-outlinedBorder) 8%, var(--joy-palette-neutral-outlinedBorder) 92%, transparent)' }} />
                                        </td>
                                    ) : (
                                        Array.from({ length: colCount }, (_, c) => {
                                            const editing = edit !== null && edit.r === r && edit.c === c;
                                            const computed = targets[`${r},${c}`];
                                            return (
                                                <td
                                                    key={c}
                                                    style={cellStyle(r, c) as any}
                                                    title={computed ? computed : undefined}
                                                    onMouseDown={e => {
                                                        if (editing) return;
                                                        if (e.shiftKey) {
                                                            setFocus({ r, c });
                                                        } else {
                                                            setAnchor({ r, c });
                                                            setFocus({ r, c });
                                                            setDragging(true);
                                                        }
                                                        setBar(null);
                                                        focusGrid();
                                                    }}
                                                    onMouseEnter={() => {
                                                        if (dragging) setFocus({ r, c });
                                                    }}
                                                    onDoubleClick={() => startEdit(r, c)}
                                                >
                                                    {editing ? (
                                                        <input
                                                            ref={editRef}
                                                            value={edit!.value}
                                                            onChange={e => setEdit({ r, c, value: e.target.value })}
                                                            onBlur={() => commitEdit(null)}
                                                            onKeyDown={e => {
                                                                e.stopPropagation();
                                                                if (e.key === 'Enter') {
                                                                    e.preventDefault();
                                                                    commitEdit({ dr: e.shiftKey ? -1 : 1, dc: 0 });
                                                                } else if (e.key === 'Tab') {
                                                                    e.preventDefault();
                                                                    commitEdit({ dr: 0, dc: e.shiftKey ? -1 : 1 });
                                                                } else if (e.key === 'Escape') {
                                                                    e.preventDefault();
                                                                    setEdit(null);
                                                                    focusGrid();
                                                                }
                                                            }}
                                                            style={{
                                                                width: '100%',
                                                                border: 'none',
                                                                outline: 'none',
                                                                background: 'transparent',
                                                                font: 'inherit',
                                                                color: 'inherit',
                                                            }}
                                                        />
                                                    ) : (
                                                        <>
                                                            {OT.cellAt(rows, r, c)}
                                                            {computed !== undefined && (
                                                                <span
                                                                    style={{
                                                                        position: 'absolute',
                                                                        top: 0,
                                                                        right: 0,
                                                                        width: 0,
                                                                        height: 0,
                                                                        borderTop: `5px solid ${highlightColor(computed) || 'var(--joy-palette-warning-500)'}`,
                                                                        borderLeft: '5px solid transparent',
                                                                        opacity: COMPUTED_MARK_OPACITY,
                                                                    }}
                                                                />
                                                            )}
                                                        </>
                                                    )}
                                                </td>
                                            );
                                        })
                                    )}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </Box>
            </Sheet>

            {/* Status bar */}
            <Sheet variant="outlined" sx={{ ...panelSx, px: 1.25, py: 0.5, display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap' }}>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {rows.length} rows &times; {colCount} cols
                </Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    Selected {rect.r1 - rect.r0 + 1} &times; {rect.c1 - rect.c0 + 1}
                </Typography>
                {stats.numeric > 0 && (
                    <>
                        <Typography level="body-xs">Sum <b>{Number(stats.sum.toFixed(6))}</b></Typography>
                        <Typography level="body-xs">Avg <b>{Number((stats.sum / stats.numeric).toFixed(6))}</b></Typography>
                        <Typography level="body-xs">Min <b>{stats.min}</b></Typography>
                        <Typography level="body-xs">Max <b>{stats.max}</b></Typography>
                    </>
                )}
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Count {stats.count}</Typography>
                <Box sx={{ flex: 1 }} />
                {props.message !== '' && (
                    <Typography level="body-xs" color="danger">{props.message}</Typography>
                )}
                {dirty && <Chip size="sm" color="warning" variant="soft" sx={{ borderRadius: '7px' }}>Unsaved changes</Chip>}
            </Sheet>

            <CellChart
                open={chartOpen}
                onClose={() => { setChartOpen(false); focusGrid(); }}
                series={chartSeries}
                title={name || table.Name || 'Selection'}
            />
        </Box>
    );
}

// A dot and a word, for saying what a colour on the grid means.
function Legend(props: { color: string; label: string }) {
    return (
        <Box sx={{ display: 'flex', gap: 0.5, alignItems: 'center', flex: 'none' }}>
            <Box sx={{ width: 8, height: 8, borderRadius: '50%', backgroundColor: props.color }} />
            <Typography level="body-xs" sx={{ color: 'text.tertiary', whiteSpace: 'nowrap' }}>{props.label}</Typography>
        </Box>
    );
}
