function getStatusIcon(status: string): React.ReactNode | undefined {
  switch (status) {
    case 'DONE': return <CheckRoundedIcon />;
    case 'IN-PROGRESS':
    case 'INPROGRESS': return <AutorenewRoundedIcon />;
    case 'TODO': return <RadioButtonUncheckedIcon />;
    case 'NEXT': return <SkipNextRoundedIcon />;
    case 'WAITING':
    case 'BLOCKED': return <HourglassEmptyRoundedIcon />;
    case 'HOLD':
    case 'PAUSED': return <PauseRoundedIcon />;
    case 'CANCELLED':
    case 'CANCELED': return <CancelRoundedIcon />;
    case 'STARTED': return <PlayArrowRoundedIcon />;
    case 'PHONE': return <PhoneRoundedIcon />;
    case 'MEETING': return <GroupsRoundedIcon />;
    default: return <BlockIcon />;
  }
}

function getStatusColor(status: string): ColorPaletteProp | undefined {
  switch (status) {
    case 'DONE': return 'success';
    case 'IN-PROGRESS':
    case 'INPROGRESS':
    case 'STARTED': return 'warning';
    case 'TODO': return 'danger';
    case 'NEXT': return undefined; // handled via sx (cyan)
    case 'WAITING':
    case 'BLOCKED': return undefined; // handled via sx (orange/yellow)
    case 'HOLD':
    case 'PAUSED': return undefined; // handled via sx (purple)
    case 'PHONE':
    case 'MEETING': return undefined; // handled via sx (indigo)
    case 'CANCELLED':
    case 'CANCELED': return undefined; // handled via sx (plum)
    case 'BACKLOG': return undefined; // handled via sx (gold)
    default: return 'neutral';
  }
}

function getStatusCustomSx(status: string): object | null {
  switch (status) {
    case 'HOLD':
    case 'PAUSED':
      return { bgcolor: 'rgba(155, 89, 182, 0.15)', color: 'rgb(125, 60, 152)' };
    case 'WAITING':
    case 'BLOCKED':
      return { bgcolor: 'rgba(243, 156, 18, 0.15)', color: 'rgb(211, 120, 0)' };
    case 'PHONE':
    case 'MEETING':
      return { bgcolor: 'rgba(63, 81, 181, 0.15)', color: 'rgb(48, 63, 159)' };
    case 'CANCELLED':
    case 'CANCELED':
      return { bgcolor: 'rgba(142, 68, 173, 0.12)', color: 'rgb(142, 68, 173)' };
    case 'BACKLOG':
      return { bgcolor: 'rgba(184, 148, 0, 0.12)', color: 'rgb(164, 128, 0)' };
    case 'NEXT':
      return { bgcolor: 'rgba(0, 188, 212, 0.12)', color: 'rgb(0, 151, 167)' };
    default:
      return null;
  }
}


function matchTags(active: any, row: any) {
  if (!active) {
    return true;
  }
  if (!row) {
    return false;
  }
  if (!row.Tags || row.Tags.length < active.length) {
    return false;
  }
  let ok = true;
  active.forEach((tag: string) => {
    let have = false;
    row.Tags.forEach((rtag: string) => {
      if (rtag === tag) {
        have = true;
      }
    });
    if (!have) {
      ok = false;
    }
  })
  return ok;
}

function descendingComparator<T>(a: T, b: T, orderBy: keyof T) {
  if (b[orderBy] < a[orderBy]) {
    return -1;
  }
  if (b[orderBy] > a[orderBy]) {
    return 1;
  }
  return 0;
}

type Order = 'asc' | 'desc';

function getComparator<Key extends keyof any>(
  order: Order,
  orderBy: Key,
): (
  a: { [key in Key]: number | string },
  b: { [key in Key]: number | string },
) => number {
  return order === 'desc'
    ? (a, b) => descendingComparator(a, b, orderBy)
    : (a, b) => -descendingComparator(a, b, orderBy);
}

// Since 2020 all major browsers ensure sort stability with Array.prototype.sort().
// stableSort() brings sort stability to non-modern browsers (notably IE11). If you
// only support modern browsers you can replace stableSort(exampleArray, exampleComparator)
// with exampleArray.slice().sort(exampleComparator)
function stableSort<T>(array: readonly T[], comparator: (a: T, b: T) => number) {
  if(array) {
    const stabilizedThis = array.map((el, index) => [el, index] as [T, number]);
    stabilizedThis.sort((a, b) => {
      const order = comparator(a[0], b[0]);
      if (order !== 0) {
        return order;
      }
      return a[1] - b[1];
    });
    return stabilizedThis.map((el) => el[0]);
  } else {
    return array;
  }
}

function ClockTimer({startTime}: {startTime: string}) {
  const [elapsed, setElapsed] = React.useState('');
  React.useEffect(() => {
    const start = new Date(startTime).getTime();
    const update = () => {
      const diff = Math.max(0, Date.now() - start);
      const hrs = Math.floor(diff / 3600000);
      const mins = Math.floor((diff % 3600000) / 60000);
      const secs = Math.floor((diff % 60000) / 1000);
      setElapsed(hrs > 0 ? `${hrs}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}` : `${mins}:${String(secs).padStart(2, '0')}`);
    };
    update();
    const interval = setInterval(update, 1000);
    return () => clearInterval(interval);
  }, [startTime]);
  return (
    <Chip size="sm" variant="soft" color="success" startDecorator={<TimerRoundedIcon sx={{ fontSize: 14 }} />} sx={{ fontFamily: 'monospace', fontSize: '11px' }}>
      {elapsed}
    </Chip>
  );
}

