function propsTooltipContent(props: Record<string, string>): React.ReactNode {
  const entries = Object.entries(props);
  if (entries.length === 0) return 'No properties';
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.25, py: 0.5 }}>
      {entries.map(([k, v]) => (
        <Typography key={k} level="body-xs" sx={{ fontFamily: 'monospace', fontSize: '11px' }}>
          <strong>{k}:</strong> {v}
        </Typography>
      ))}
    </Box>
  );
}

function OrgProps({row, onPropsClick}: {row: any, onPropsClick?: (row: any) => void}) {
  const props: Record<string, string> = row.Props || {};
  const keys = Object.keys(props);
  const count = keys.length;
  let label: React.ReactNode;
  if (count === 0) {
    label = <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>+ prop</Typography>;
  } else if (count === 1) {
    label = <Typography level="body-xs">{keys[0]}</Typography>;
  } else {
    label = <Typography level="body-xs">{count} props</Typography>;
  }
  return (
    <td>
      <Tooltip title={propsTooltipContent(props)} variant="outlined" placement="top" arrow>
        <Box
          onClick={() => onPropsClick?.(row)}
          sx={{ cursor: 'pointer', '&:hover': { opacity: 0.7 } }}
        >
          {label}
        </Box>
      </Tooltip>
    </td>
  );
}

