function OrgHeadline({row, isEditing, onCommit, onCancel, onStartEdit, clockedInKey, clockStartTime, clockKeyForRow}: {row: any, isEditing: boolean, onCommit: (value: string) => void, onCancel: () => void, onStartEdit: (row: any) => void, clockedInKey?: string | null, clockStartTime?: string | null, clockKeyForRow?: (row: any) => string}) {
  const inputRef = React.useRef<HTMLInputElement>(null);
  const blurTimeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const committedRef = React.useRef(false);
  const [localValue, setLocalValue] = React.useState(row.Headline);
  const [logbook, setLogbook] = React.useState<Array<{start: string, end: string, mins: number}> | null>(null);
  const logbookFetchedRef = React.useRef<string | null>(null);

  const fetchLogbook = () => {
    if (logbookFetchedRef.current === row.Hash) return;
    logbookFetchedRef.current = row.Hash;
    Db.ODb.getLogbook(row.Hash).then((data) => {
      if (data && !Array.isArray(data) && data.entries) {
        setLogbook(data.entries.slice(0, 10));
      } else {
        setLogbook([]);
      }
    }).catch(() => setLogbook([]));
  };

  React.useEffect(() => {
    if (isEditing) {
      setLocalValue(row.Headline);
      committedRef.current = false;
      const t = setTimeout(() => {
        if (inputRef.current) {
          inputRef.current.focus();
          inputRef.current.select();
        }
      }, 50);
      return () => clearTimeout(t);
    }
  }, [isEditing]);

  React.useEffect(() => {
    return () => {
      if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current);
    };
  }, []);

  const handleBlur = () => {
    blurTimeoutRef.current = setTimeout(() => {
      if (!committedRef.current) {
        committedRef.current = true;
        onCancel();
      }
    }, 150);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (!committedRef.current) {
        committedRef.current = true;
        if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current);
        onCommit(localValue);
      }
    }
    if (e.key === 'Escape') {
      e.preventDefault();
      if (!committedRef.current) {
        committedRef.current = true;
        if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current);
        onCancel();
      }
    }
  };

  return (
    <td>
      <Box
        sx={{ display: 'flex', gap: 2, alignItems: 'center' }}
        onContextMenu={(e) => { e.preventDefault(); onStartEdit(row); }}
      >
        {isEditing ? (
          <input
            ref={inputRef}
            value={localValue}
            onChange={(e) => setLocalValue(e.target.value)}
            onKeyDown={handleKeyDown}
            onBlur={handleBlur}
            style={{ fontSize: '0.75rem', fontFamily: 'inherit', width: '100%', padding: '2px 4px', border: '1px solid var(--joy-palette-primary-outlinedBorder)', borderRadius: 4, outline: 'none' }}
          />
        ) : (
          <Tooltip
            variant="outlined"
            placement="top-start"
            arrow
            onOpen={fetchLogbook}
            title={
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.25, py: 0.5, maxWidth: 320 }}>
                <Typography level="body-xs" sx={{ fontWeight: 'bold' }}>{row.Headline}</Typography>
                <Typography level="body-xs" sx={{ fontFamily: 'monospace', fontSize: '10px', color: 'text.tertiary' }}>
                  {row.Filename?.replace(/^.*\//, '')}:{row.LineNum}
                </Typography>
                {clockedInKey && clockKeyForRow && clockedInKey === clockKeyForRow(row) && clockStartTime && (
                  <Typography level="body-xs" sx={{ color: 'success.plainColor', fontSize: '10px' }}>
                    ⏱ Clocked in since {new Date(clockStartTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </Typography>
                )}
                {logbook && logbook.length > 0 && (
                  <Box sx={{ mt: 0.5, borderTop: '1px solid', borderColor: 'divider', pt: 0.5 }}>
                    <Typography level="body-xs" sx={{ fontWeight: 'bold', fontSize: '10px', mb: 0.25 }}>Logbook</Typography>
                    {logbook.map((entry, i) => {
                      const start = new Date(entry.start);
                      const end = entry.end ? new Date(entry.end) : null;
                      const hrs = Math.floor(entry.mins / 60);
                      const mins = Math.round(entry.mins % 60);
                      const durStr = hrs > 0 ? `${hrs}h${mins > 0 ? ` ${mins}m` : ''}` : `${mins}m`;
                      const dateStr = start.toLocaleDateString([], { month: 'short', day: 'numeric' });
                      const timeStr = start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                      const endStr = end ? end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '...';
                      return (
                        <Typography key={i} level="body-xs" sx={{ fontFamily: 'monospace', fontSize: '9px', color: 'text.secondary' }}>
                          {dateStr} {timeStr}–{endStr} ({durStr})
                        </Typography>
                      );
                    })}
                  </Box>
                )}
              </Box>
            }
          >
            <Typography level="body-xs">{row.Headline}</Typography>
          </Tooltip>
        )}
      </Box>
    </td>
  );
}

